function fewest_steps(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  if (grid[0][0] === 1 || grid[rows - 1][cols - 1] === 1) return -1;
  const seen = new Set([0]);
  let queue = [[0, 0]];
  let steps = 0;
  while (queue.length) {
    const next = [];
    for (const [r, c] of queue) {
      if (r === rows - 1 && c === cols - 1) return steps;
      for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nr = r + dr;
        const nc = c + dc;
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] === 0 && !seen.has(nr * cols + nc)) {
          seen.add(nr * cols + nc);
          next.push([nr, nc]);
        }
      }
    }
    queue = next;
    steps++;
  }
  return -1;
}

